import {renderDiagram} from './visual.js?v=20261023-physicscomplete01';
import {halfLedger} from './half-equations.js?v=20261023-physicscomplete01';
const txt=(x,y,s,size=14)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="#f8f6f2" font-family="sans-serif" font-size="${size}">${s}</text>`;
export function showIndustry(kind='cell',result='',equation=''){
 if(kind==='half'){const ledger=halfLedger(equation);let body='<p class="diagram-caption">Atom counts and total charge must match on both sides.</p>';if(ledger){const elements=[...new Set(ledger.flatMap(r=>Object.keys(r.atoms)))];body=`<table class="aqueous-observations"><caption>Your balance ledger</caption><thead><tr><th>Count</th><th>Left</th><th>Right</th></tr></thead><tbody>${elements.map(e=>`<tr><th>${e} atoms</th><td>${ledger[0].atoms[e]||0}</td><td>${ledger[1].atoms[e]||0}</td></tr>`).join('')}<tr><th>Total charge</th><td>${ledger[0].charge}</td><td>${ledger[1].charge}</td></tr></tbody></table><p class="diagram-caption">Matching totals are necessary. The species and electrode reaction must also be correct.</p>`;}else if(equation)body='<p class="diagram-caption">Use chemical symbols, whole-number coefficients, an arrow and e−. This ledger supports the species used in this lesson.</p>';
 renderDiagram('Conserve atoms and charge','Electrode half-equation',body,'SYMBOLIC BALANCE LEDGER · SUPPORTED GCSE SPECIES');return;}
 const consumed=kind==='anode'||result==='consumed',lower=result==='mixture';renderDiagram('Inside the extraction cell',consumed?'Oxygen + carbon → carbon dioxide':lower?'Cryolite lowers the operating temperature':'Aluminium oxide dissolved in molten cryolite',`<svg class="lab-svg" viewBox="0 0 440 310" role="img" aria-label="Schematic aluminium extraction cell. Positive carbon anodes dip into molten electrolyte above liquid aluminium. Negative carbon lining acts as cathode. ${consumed?'Carbon anodes shorten as oxygen reacts with carbon to form carbon dioxide.':''}"><defs><linearGradient id="bath" x2="0" y2="1"><stop stop-color="#ed8b78" stop-opacity=".7"/><stop offset="1" stop-color="#ed8b78" stop-opacity=".15"/></linearGradient></defs>${txt(220,23,'+ Carbon anodes')}${txt(220,56,consumed?'Consumed by oxygen → CO₂':lower?'Less heating; current still needed':'Connected to positive supply',12)}<path d="M55 100V252H385V100" fill="#182e44" stroke="#71808c" stroke-width="13"/><path d="M65 114H375V215H65Z" fill="url(#bath)"/><path d="M65 215H375V242H65Z" fill="#b7c8d6"/><path d="M145 75V${consumed?139:174} M295 75V${consumed?139:174}" stroke="#71808c" stroke-width="34"/>${txt(220,199,'Molten electrolyte',13)}${txt(220,236,'Liquid aluminium',13).replace('fill="#f8f6f2"','fill="#182e44"')}<path d="M55 254L34 280H170" stroke="#b7c8d6" fill="none"/>${txt(256,286,'− Carbon lining / cathode',13)}${consumed?'<circle cx="145" cy="151" r="5" fill="#f8f6f2"/><circle cx="295" cy="151" r="5" fill="#f8f6f2"/>':''}</svg><p class="diagram-caption">Cross-section, not to scale. Layers, anode wear and ion chemistry are simplified; no rate or temperature simulation.</p>`,'INDUSTRIAL CELL · SCHEMATIC CROSS-SECTION');
}
